foreach ($manifest['php'] ?? [] as $package) {
    $file = $root.'/'.$package['path'].'/composer.json';
50→    try {
        $composer = readJson($file);
    } catch (Throwable $e) {
        $errors[] = "{$package['name']}: {$e->getMessage()}";

        continue;
    }

