input.command:
set -euo pipefail
TMP=/tmp/grok-vostrikov/p75-exempt
rm -rf "$TMP"
mkdir -p "$TMP/release" "$TMP/.github/workflows" "$TMP/packages/vue"
cp release/packages.json "$TMP/release/packages.json"
cp .github/workflows/monorepo-split.yml "$TMP/.github/workflows/monorepo-split.yml"
cp packages/vue/package.json "$TMP/packages/vue/package.json"
for p in core media drive documents filament azgard vaulter; do
  mkdir -p "$TMP/packages/$p"
  cp "packages/$p/composer.json" "$TMP/packages/$p/composer.json"
done
php -r '
$p = "'$TMP'/packages/azgard/composer.json";
$j = json_decode(file_get_contents($p), true);
$j["require"]["axiomasoft/azguard"] = "^0.2";
$j["require-dev"]["axiomasoft/azguard"] = "dev-main";
file_put_contents($p, json_encode($j, JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)."\n");
echo "require=", $j["require"]["axiomasoft/azguard"], " require-dev=", $j["require-dev"]["axiomasoft/azguard"], "\n";
'
echo '===== check-versions on shipped azgard that still dev-requires azguard ====='
set +e
php scripts/release/check-versions.php --root="$TMP"
echo "check_versions_exit=$?"
echo '===== verify --excluded (same tree via RELEASE_MANIFEST + real root cannot see temp composer) ====='
# verify always reads $root/$path from the repo of the script. Reproduce its predicate against the temp composer.
php -r '
$c = json_decode(file_get_contents("'$TMP'/packages/azgard/composer.json"), true);
$req = $c["require"]["axiomasoft/azguard"];
$dev = str_starts_with($req, "dev-") || str_contains($req, "@dev") || str_ends_with($req, "-dev");
echo "build_would_skip=".($dev?"yes":"no")." require=$req\n";
'
jq -e --arg u axiomasoft/azguard '(.require[$u] // "") | test("^dev-|@dev|-dev$")' "$TMP/packages/azgard/composer.json" >/dev/null && echo verify_would_exclude=yes || echo verify_would_exclude=no
set -e
